EXPORT ZZT_IMSTD() BEGIN
LOCAL R,O:={};
HComplex:=10; LOCAL T:=stddev({1,3},{-1,3});
IFERR R:=T; O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=approx(T); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=RE(approx(T)); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=IM(approx(T)); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
RETURN O; END;

