EXPORT ZZT_IMSTD() BEGIN
LOCAL R,O:={};
HComplex:=11;
LOCAL T:=stddev({1,3},{-1,3});
IFERR R:=approx(T)+2; O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=TYPE(approx(T)*approx(T)); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=ROUND(RE(approx(T)*approx(T)),10); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=IM(approx(T)*approx(T)); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
RETURN O; END;

